import {
  Body,
  Head as EmailHead,
  Html,
  Preview,
  Section,
  Row,
  Column,
  Link,
  Heading,
  Text,
  Img,
} from "jsx-email";
import { Fragment } from "react";

import { DefaultFonts } from "@/components/email/font-default";
import { EmailTailwind } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

type TeamCardsDetails_TwoColumnTeamCardsWithDetailsVariant =
  | "default"
  | "boxed"
  | "accent";

interface TeamCardsDetails_TwoColumnTeamCardsWithDetailsProps {
  theme?: EmailTheme;
  avatarSrc1?: string;
  avatarAlt1?: string;
  name1?: string;
  role1?: string;
  bio1?: string;
  email1?: string;
  avatarSrc2?: string;
  avatarAlt2?: string;
  name2?: string;
  role2?: string;
  bio2?: string;
  email2?: string;
  variant?: TeamCardsDetails_TwoColumnTeamCardsWithDetailsVariant;
}

const TeamCardsDetails_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const TeamCardsDetails_responsiveStyles = `
    @media only screen and (max-width: 599px) {
      .team-details-stack { display: block !important; width: 100% !important; }
      .team-details-gap { line-height: 24px !important; }
    }
  `;

const TeamCardsDetails_SocialLinks = ({
  accent,
  lastIcon,
}: {
  accent: boolean;
  lastIcon: "instagram" | "linkedin";
}) => {
  const suffix = accent ? "light" : "dark";
  const icons = ["facebook", "x", lastIcon] as const;
  return (
    <Section align="left" style={{ width: "80px" }}>
      <Fragment>
        <Row>
          {icons.map((icon, index) => (
            <Fragment key={icon}>
              {index > 0 ? (
                <Column style={{ width: "16px" }}>&zwj;</Column>
              ) : null}
              <Column style={{ width: "16px" }}>
                <Link href={`https://${icon === "x" ? "x" : icon}.com`}>
                  <Img
                    alt=""
                    src={emailAsset(`icon-${icon}-${suffix}.png`)}
                    width="16"
                  />
                </Link>
              </Column>
            </Fragment>
          ))}
        </Row>
      </Fragment>
    </Section>
  );
};

interface TeamCardsDetails_DetailsCardProps {
  accent: boolean;
  avatarAlt: string;
  avatarSrc: string;
  bio: string;
  email: string;
  lastIcon: "instagram" | "linkedin";
  name: string;
  role: string;
  variant: TeamCardsDetails_TwoColumnTeamCardsWithDetailsVariant;
}

const TeamCardsDetails_DetailsCard = ({
  accent,
  avatarAlt,
  avatarSrc,
  bio,
  email,
  lastIcon,
  name,
  role,
  variant,
}: TeamCardsDetails_DetailsCardProps) => {
  const boxed = variant !== "default";
  const backgroundColor = accent ? "#030712" : "#f9fafb";
  const content = (
    <>
      <Heading
        style={{
          color: accent ? "#fffffe" : "#030712",
          fontFamily: TeamCardsDetails_fontFamily,
          fontSize: "16px",
          fontWeight: 600,
          lineHeight: "24px",
          margin: 0,
        }}
        as="h3"
      >
        {name}
      </Heading>
      <Text
        style={{
          color: accent ? "#d1d5db" : "#4b5563",
          fontFamily: TeamCardsDetails_fontFamily,
          fontSize: "14px",
          lineHeight: "20px",
          margin: 0,
        }}
      >
        {role}
      </Text>
      <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
      <Text
        style={{
          color: accent ? "#9ca3af" : "#4b5563",
          fontFamily: TeamCardsDetails_fontFamily,
          fontSize: "16px",
          lineHeight: "24px",
          margin: 0,
        }}
      >
        {bio}
      </Text>
      <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
      <Text
        style={{
          fontFamily: TeamCardsDetails_fontFamily,
          fontSize: "14px",
          fontWeight: 500,
          lineHeight: "20px",
          margin: 0,
        }}
      >
        <Link
          href={`mailto:${email}`}
          style={{ color: "#4f46e5", textDecoration: "none" }}
        >
          {email}
        </Link>
      </Text>
      <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
      <TeamCardsDetails_SocialLinks accent={accent} lastIcon={lastIcon} />
    </>
  );
  if (!boxed) {
    return (
      <>
        <Img
          alt={avatarAlt}
          src={avatarSrc}
          style={{
            borderRadius: "8px",
            maxWidth: "100%",
            verticalAlign: "middle",
          }}
          width="264"
        />
        <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
        {content}
      </>
    );
  }
  return (
    <>
      <Section
        style={{
          backgroundColor,
          borderRadius: "8px 8px 0 0",
        }}
      >
        <Img
          alt={avatarAlt}
          src={avatarSrc}
          style={{
            borderRadius: "8px",
            maxWidth: "100%",
            verticalAlign: "middle",
          }}
          width="264"
        />
      </Section>
      <Section style={{ width: "100%" }}>
        <Fragment>
          <Row>
            <Column
              style={{
                backgroundColor,
                borderRadius: "0 0 8px 8px",
                padding: "16px 24px 24px",
              }}
            >
              {content}
            </Column>
          </Row>
        </Fragment>
      </Section>
    </>
  );
};

const TeamCardsDetails_TwoColumnTeamCardsWithDetailsSection = ({
  avatarAlt1 = "",
  avatarAlt2 = "",
  avatarSrc1 = emailAsset("teams/member-1-lg.jpg"),
  avatarSrc2 = emailAsset("teams/member-2-lg.jpg"),
  bio1 = "Imagination is more important than knowledge. For knowledge is limited, whereas imagination embraces.",
  bio2 = "Imagination is more important than knowledge. For knowledge is limited, whereas imagination embraces.",
  email1 = "jadam@example.com",
  email2 = "hpetersson@example.com",
  name1 = "Jason Adam",
  name2 = "Henrik Petersson",
  role1 = "Senior Developer",
  role2 = "Senior UX/UI designer",
  variant = "default",
}: Omit<TeamCardsDetails_TwoColumnTeamCardsWithDetailsProps, "theme">) => {
  const accent = variant === "accent";
  return (
    <>
      <style>{TeamCardsDetails_responsiveStyles}</style>
      <Section style={{ backgroundColor: "#f1f5f9", width: "100%" }}>
        <Fragment>
          <Row>
            <Column>&zwj;</Column>
            <Column
              style={{
                backgroundColor: "#fffffe",
                maxWidth: "100%",
                padding: "44px 24px",
                width: "600px",
              }}
            >
              <Section style={{ width: "100%" }}>
                <Fragment>
                  <Row>
                    <Column
                      className="team-details-stack"
                      style={{ verticalAlign: "top", width: "264px" }}
                    >
                      <TeamCardsDetails_DetailsCard
                        accent={accent}
                        avatarAlt={avatarAlt1}
                        avatarSrc={avatarSrc1}
                        bio={bio1}
                        email={email1}
                        lastIcon="linkedin"
                        name={name1}
                        role={role1}
                        variant={variant}
                      />
                    </Column>
                    <Column
                      className="team-details-stack team-details-gap"
                      style={{ lineHeight: 0, width: "24px" }}
                    >
                      &zwj;
                    </Column>
                    <Column
                      className="team-details-stack"
                      style={{ verticalAlign: "top", width: "264px" }}
                    >
                      <TeamCardsDetails_DetailsCard
                        accent={accent}
                        avatarAlt={avatarAlt2}
                        avatarSrc={avatarSrc2}
                        bio={bio2}
                        email={email2}
                        lastIcon="instagram"
                        name={name2}
                        role={role2}
                        variant={variant}
                      />
                    </Column>
                  </Row>
                </Fragment>
              </Section>
            </Column>
            <Column>&zwj;</Column>
          </Row>
        </Fragment>
      </Section>
    </>
  );
};

const TeamCardsDetails_TwoColumnTeamCardsWithDetails = ({
  theme = defaultTheme,
  ...props
}: TeamCardsDetails_TwoColumnTeamCardsWithDetailsProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
    </EmailHead>
    <Preview>Meet the team</Preview>
    <EmailTailwind theme={theme}>
      <Body className="m-0">
        <TeamCardsDetails_TwoColumnTeamCardsWithDetailsSection {...props} />
      </Body>
    </EmailTailwind>
  </Html>
);

TeamCardsDetails_TwoColumnTeamCardsWithDetails.PreviewProps = {
  theme: defaultTheme,
  variant: "default",
} satisfies TeamCardsDetails_TwoColumnTeamCardsWithDetailsProps;

const __TeamCardsDetails = TeamCardsDetails_TwoColumnTeamCardsWithDetails;

type TeamCards_TwoColumnTeamCardsVariant =
  | "default"
  | "boxed"
  | "accent"
  | "boxed-alt"
  | "accent-alt"
  | "rounded"
  | "rounded-accent";

interface TeamCards_TwoColumnTeamCardsProps {
  theme?: EmailTheme;
  avatarSrc1?: string;
  avatarAlt1?: string;
  name1?: string;
  role1?: string;
  avatarSrc2?: string;
  avatarAlt2?: string;
  name2?: string;
  role2?: string;
  variant?: TeamCards_TwoColumnTeamCardsVariant;
}

const TeamCards_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const TeamCards_responsiveStyles = `
    @media only screen and (max-width: 599px) {
      .team-stack { display: block !important; width: 100% !important; }
      .team-gap { line-height: 24px !important; }
      .team-round-image { max-width: 144px !important; }
    }
  `;

const TeamCards_socialIcons = {
  dark: {
    facebook: emailAsset("icon-facebook-dark.png"),
    instagram: emailAsset("icon-instagram-dark.png"),
    linkedin: emailAsset("icon-linkedin-dark.png"),
    x: emailAsset("icon-x-dark.png"),
  },
  light: {
    facebook: emailAsset("icon-facebook-light.png"),
    instagram: emailAsset("icon-instagram-light.png"),
    linkedin: emailAsset("icon-linkedin-light.png"),
    x: emailAsset("icon-x-light.png"),
  },
};

const TeamCards_SocialLinks = ({
  accent,
  center,
  lastIcon,
}: {
  accent: boolean;
  center: boolean;
  lastIcon: "instagram" | "linkedin";
}) => {
  const icons = accent
    ? TeamCards_socialIcons.light
    : TeamCards_socialIcons.dark;
  const links = ["facebook", "x", lastIcon] as const;
  return (
    <Section align={center ? "center" : "left"} style={{ width: "80px" }}>
      <Fragment>
        <Row>
          {links.map((icon, index) => (
            <Fragment key={icon}>
              {index > 0 ? (
                <Column style={{ width: "16px" }}>&zwj;</Column>
              ) : null}
              <Column style={{ width: "16px" }}>
                <Link href={`https://${icon === "x" ? "x" : icon}.com`}>
                  <Img alt="" src={icons[icon]} width="16" />
                </Link>
              </Column>
            </Fragment>
          ))}
        </Row>
      </Fragment>
    </Section>
  );
};

interface TeamCards_TeamCardProps {
  accent: boolean;
  avatarAlt: string;
  avatarSrc: string;
  lastIcon: "instagram" | "linkedin";
  name: string;
  role: string;
  variant: TeamCards_TwoColumnTeamCardsVariant;
}

const TeamCards_TeamCard = ({
  accent,
  avatarAlt,
  avatarSrc,
  lastIcon,
  name,
  role,
  variant,
}: TeamCards_TeamCardProps) => {
  const rounded = variant === "rounded" || variant === "rounded-accent";
  const boxed = variant !== "default";
  const alt = variant === "boxed-alt" || variant === "accent-alt";
  const cardBackground = accent ? "#030712" : "#f9fafb";
  const content = (
    <>
      <Heading
        style={{
          color: accent ? "#fffffe" : "#030712",
          fontFamily: TeamCards_fontFamily,
          fontSize: "16px",
          fontWeight: 600,
          lineHeight: "24px",
          margin: 0,
          textAlign: rounded ? "center" : "left",
        }}
        as="h3"
      >
        {name}
      </Heading>
      <Text
        style={{
          color: accent ? "#d1d5db" : "#4b5563",
          fontFamily: TeamCards_fontFamily,
          fontSize: "14px",
          lineHeight: "20px",
          margin: 0,
          textAlign: rounded ? "center" : "left",
        }}
      >
        {role}
      </Text>
      <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
      <Section align={rounded ? "center" : undefined}>
        <Fragment>
          <Row>
            <Column>
              <TeamCards_SocialLinks
                accent={accent}
                center={rounded}
                lastIcon={lastIcon}
              />
            </Column>
          </Row>
        </Fragment>
      </Section>
    </>
  );
  if (rounded) {
    return (
      <Section style={{ width: "100%" }}>
        <Fragment>
          <Row>
            <Column
              style={{
                backgroundColor: cardBackground,
                borderRadius: "8px",
                padding: "16px 24px 24px",
              }}
            >
              <Section style={{ textAlign: "center" }}>
                <Img
                  alt={avatarAlt}
                  className="team-round-image"
                  src={avatarSrc}
                  style={{
                    borderRadius: "9999px",
                    maxWidth: "100%",
                    verticalAlign: "middle",
                  }}
                  width="188"
                />
              </Section>
              <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
              {content}
            </Column>
          </Row>
        </Fragment>
      </Section>
    );
  }
  if (boxed) {
    return (
      <>
        <Section
          style={{
            backgroundColor: cardBackground,
            borderRadius: "8px 8px 0 0",
          }}
        >
          <Img
            alt={avatarAlt}
            src={avatarSrc}
            style={{
              borderRadius: alt ? "8px 8px 0 0" : "8px",
              maxWidth: "100%",
              verticalAlign: "middle",
            }}
            width="264"
          />
        </Section>
        <Section style={{ width: "100%" }}>
          <Fragment>
            <Row>
              <Column
                style={{
                  backgroundColor: cardBackground,
                  borderRadius: "0 0 8px 8px",
                  padding: "16px 24px 24px",
                }}
              >
                {content}
              </Column>
            </Row>
          </Fragment>
        </Section>
      </>
    );
  }
  return (
    <>
      <Img
        alt={avatarAlt}
        src={avatarSrc}
        style={{
          borderRadius: "8px",
          maxWidth: "100%",
          verticalAlign: "middle",
        }}
        width="264"
      />
      <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
      {content}
    </>
  );
};

const TeamCards_TwoColumnTeamCardsSection = ({
  avatarAlt1 = "",
  avatarAlt2 = "",
  avatarSrc1,
  avatarSrc2,
  name1 = "Jason Adam",
  name2 = "Henrik Petersson",
  role1 = "Senior Developer",
  role2 = "Senior UX/UI designer",
  variant = "default",
}: Omit<TeamCards_TwoColumnTeamCardsProps, "theme">) => {
  const rounded = variant === "rounded" || variant === "rounded-accent";
  const accent =
    variant === "accent" ||
    variant === "accent-alt" ||
    variant === "rounded-accent";
  return (
    <>
      <style>{TeamCards_responsiveStyles}</style>
      <Section style={{ backgroundColor: "#f1f5f9", width: "100%" }}>
        <Fragment>
          <Row>
            <Column>&zwj;</Column>
            <Column
              style={{
                backgroundColor: "#fffffe",
                maxWidth: "100%",
                padding: "44px 24px",
                width: "600px",
              }}
            >
              <Section style={{ width: "100%" }}>
                <Fragment>
                  <Row>
                    <Column
                      className="team-stack"
                      style={{ verticalAlign: "top", width: "264px" }}
                    >
                      <TeamCards_TeamCard
                        accent={accent}
                        avatarAlt={avatarAlt1}
                        avatarSrc={
                          avatarSrc1 ??
                          emailAsset(
                            `teams/member-1-${rounded ? "md" : "lg"}.jpg`
                          )
                        }
                        lastIcon="linkedin"
                        name={name1}
                        role={role1}
                        variant={variant}
                      />
                    </Column>
                    <Column
                      className="team-stack team-gap"
                      style={{ lineHeight: 0, width: "24px" }}
                    >
                      &zwj;
                    </Column>
                    <Column
                      className="team-stack"
                      style={{ verticalAlign: "top", width: "264px" }}
                    >
                      <TeamCards_TeamCard
                        accent={accent}
                        avatarAlt={avatarAlt2}
                        avatarSrc={
                          avatarSrc2 ??
                          emailAsset(
                            `teams/member-2-${rounded ? "md" : "lg"}.jpg`
                          )
                        }
                        lastIcon="instagram"
                        name={name2}
                        role={role2}
                        variant={variant}
                      />
                    </Column>
                  </Row>
                </Fragment>
              </Section>
            </Column>
            <Column>&zwj;</Column>
          </Row>
        </Fragment>
      </Section>
    </>
  );
};

const TeamCards_TwoColumnTeamCards = ({
  theme = defaultTheme,
  ...props
}: TeamCards_TwoColumnTeamCardsProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
    </EmailHead>
    <Preview>Meet the team</Preview>
    <EmailTailwind theme={theme}>
      <Body className="m-0">
        <TeamCards_TwoColumnTeamCardsSection {...props} />
      </Body>
    </EmailTailwind>
  </Html>
);

TeamCards_TwoColumnTeamCards.PreviewProps = {
  theme: defaultTheme,
  variant: "default",
} satisfies TeamCards_TwoColumnTeamCardsProps;

const __TeamCards = TeamCards_TwoColumnTeamCards;

type TeamCompact_TwoColumnsCompactVariant =
  | "default"
  | "border-top"
  | "bordered"
  | "accent";

interface TeamCompact_TwoColumnsCompactProps {
  theme?: EmailTheme;
  avatarSrc1?: string;
  avatarAlt1?: string;
  name1?: string;
  role1?: string;
  avatarSrc2?: string;
  avatarAlt2?: string;
  name2?: string;
  role2?: string;
  variant?: TeamCompact_TwoColumnsCompactVariant;
}

const TeamCompact_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const TeamCompact_responsiveStyles = `
    @media only screen and (max-width: 599px) {
      .compact-team-stack { display: block !important; width: 100% !important; }
      .compact-team-gap { line-height: 24px !important; }
    }
  `;

const TeamCompact_SocialLinks = ({
  lastIcon,
}: {
  lastIcon: "instagram" | "linkedin";
}) => {
  const icons = ["facebook", "x", lastIcon] as const;
  return (
    <Section align="left" style={{ width: "80px" }}>
      <Fragment>
        <Row>
          {icons.map((icon, index) => (
            <Fragment key={icon}>
              {index > 0 ? (
                <Column style={{ width: "16px" }}>&zwj;</Column>
              ) : null}
              <Column style={{ width: "16px" }}>
                <Link href={`https://${icon === "x" ? "x" : icon}.com`}>
                  <Img
                    alt=""
                    src={emailAsset(`icon-${icon}-dark.png`)}
                    width="16"
                  />
                </Link>
              </Column>
            </Fragment>
          ))}
        </Row>
      </Fragment>
    </Section>
  );
};

interface TeamCompact_CompactCardProps {
  avatarAlt: string;
  avatarSrc: string;
  lastIcon: "instagram" | "linkedin";
  name: string;
  role: string;
  variant: TeamCompact_TwoColumnsCompactVariant;
}

const TeamCompact_CompactCard = ({
  avatarAlt,
  avatarSrc,
  lastIcon,
  name,
  role,
  variant,
}: TeamCompact_CompactCardProps) => {
  const boxed = variant === "bordered" || variant === "accent";
  const accent = variant === "accent";
  const member = (
    <Section style={{ width: "100%" }}>
      <Fragment>
        <Row>
          <Column style={{ verticalAlign: "top", width: "64px" }}>
            <Img
              alt={avatarAlt}
              src={avatarSrc}
              style={{
                borderRadius: "9999px",
                maxWidth: "100%",
                verticalAlign: "middle",
              }}
              width="64"
            />
          </Column>
          <Column style={{ width: boxed ? "16px" : "24px" }}>&zwj;</Column>
          <Column>
            <Heading
              style={{
                color: accent ? "#fffffe" : "#030712",
                fontFamily: TeamCompact_fontFamily,
                fontSize: "16px",
                fontWeight: 600,
                lineHeight: "24px",
                margin: 0,
              }}
              as="h3"
            >
              {name}
            </Heading>
            <Text
              style={{
                color: accent ? "#d1d5db" : "#4b5563",
                fontFamily: TeamCompact_fontFamily,
                fontSize: "14px",
                lineHeight: "20px",
                margin: 0,
              }}
            >
              {role}
            </Text>
            {boxed ? null : (
              <>
                <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
                <TeamCompact_SocialLinks lastIcon={lastIcon} />
              </>
            )}
          </Column>
        </Row>
      </Fragment>
    </Section>
  );
  if (boxed) {
    return (
      <Section style={{ width: "100%" }}>
        <Fragment>
          <Row>
            <Column
              style={{
                backgroundColor: accent ? "#030712" : undefined,
                border: accent ? undefined : "1px solid #d1d5db",
                borderRadius: "8px",
                padding: "16px",
              }}
            >
              {member}
            </Column>
          </Row>
        </Fragment>
      </Section>
    );
  }
  return (
    <>
      {variant === "border-top" ? (
        <>
          <Section
            style={{
              backgroundColor: "#030712",
              height: "2px",
              lineHeight: "1px",
            }}
          >
            &zwj;
          </Section>
          <Section style={{ lineHeight: "14px" }}>&zwj;</Section>
        </>
      ) : null}
      {member}
    </>
  );
};

const TeamCompact_TwoColumnsCompactSection = ({
  avatarAlt1 = "",
  avatarAlt2 = "",
  avatarSrc1 = emailAsset("teams/member-1-md.jpg"),
  avatarSrc2 = emailAsset("teams/member-2-md.jpg"),
  name1 = "Jason Adam",
  name2 = "Henrik Petersson",
  role1 = "Senior Developer",
  role2 = "Senior UX/UI designer",
  variant = "default",
}: Omit<TeamCompact_TwoColumnsCompactProps, "theme">) => (
  <>
    <style>{TeamCompact_responsiveStyles}</style>
    <Section style={{ backgroundColor: "#f1f5f9", width: "100%" }}>
      <Fragment>
        <Row>
          <Column>&zwj;</Column>
          <Column
            style={{
              backgroundColor: "#fffffe",
              maxWidth: "100%",
              padding: "44px 24px",
              width: "600px",
            }}
          >
            <Section style={{ width: "100%" }}>
              <Fragment>
                <Row>
                  <Column
                    className="compact-team-stack"
                    style={{ verticalAlign: "top", width: "264px" }}
                  >
                    <TeamCompact_CompactCard
                      avatarAlt={avatarAlt1}
                      avatarSrc={avatarSrc1}
                      lastIcon="linkedin"
                      name={name1}
                      role={role1}
                      variant={variant}
                    />
                  </Column>
                  <Column
                    className="compact-team-stack compact-team-gap"
                    style={{ lineHeight: 0, width: "24px" }}
                  >
                    &zwj;
                  </Column>
                  <Column
                    className="compact-team-stack"
                    style={{ verticalAlign: "top", width: "264px" }}
                  >
                    <TeamCompact_CompactCard
                      avatarAlt={avatarAlt2}
                      avatarSrc={avatarSrc2}
                      lastIcon="instagram"
                      name={name2}
                      role={role2}
                      variant={variant}
                    />
                  </Column>
                </Row>
              </Fragment>
            </Section>
          </Column>
