export interface TeamMember {
  name: string;
  role: string;
  avatar: {
    alt?: string;
    src: string;
  };
  bio?: string;
  email?: string;
}

export interface TeamProps {
  theme?: Parameters<typeof __TeamCards>[0]["theme"];
  members?: TeamMember[];
  layout?: "cards" | "compact" | "grid" | "bios";
  columns?: 2 | 3;
  appearance?: "plain" | "boxed" | "bordered" | "accent" | "rounded";
  imagePosition?: "left" | "right";
  heroImage?: {
    src: string;
    alt?: string;
  };
  details?: boolean;
  variant?:
    | Parameters<typeof __TeamCardsDetails>[0]["variant"]
    | Parameters<typeof __TeamCards>[0]["variant"]
    | Parameters<typeof __TeamCompact>[0]["variant"]
    | Parameters<typeof __TeamGrid>[0]["variant"]
    | Parameters<typeof __TeamBios>[0]["variant"];
}

const toTeamProps = (members: TeamMember[] | undefined) =>
  Object.fromEntries(
    (members ?? []).flatMap((member, index) => {
      const suffix = index + 1;
      return [
        [`avatarSrc${suffix}`, member.avatar.src],
        [`avatarAlt${suffix}`, member.avatar.alt],
        [`name${suffix}`, member.name],
        [`role${suffix}`, member.role],
        [`bio${suffix}`, member.bio],
        [`email${suffix}`, member.email],
      ];
    })
  );

export const Team = ({
  theme,
  members,
  layout = "cards",
  columns = 2,
  appearance = "plain",
  imagePosition = "left",
  heroImage,
  details,
  variant: variantOverride,
}: TeamProps) => {
  const props = { ...toTeamProps(members), theme };
  if (layout === "compact") {
    const variant = {
      accent: "accent",
      bordered: "bordered",
      boxed: "border-top",
      plain: "default",
      rounded: "default",
    }[appearance];
    return (
      <__TeamCompact
        {...props}
        variant={
          (variantOverride ?? variant) as Parameters<
            typeof __TeamCompact
          >[0]["variant"]
        }
      />
    );
  }
  if (layout === "grid" || columns === 3) {
    const variant = (() => {
      if (heroImage) {
        return "with-hero";
      }
      if (appearance === "accent") {
        return "with-accent";
      }
      if (appearance === "bordered") {
        return "bordered";
      }
      return "default";
    })();
    return (
      <__TeamGrid
        {...props}
        heroImageSrc={heroImage?.src}
        variant={
          (variantOverride ?? variant) as Parameters<
            typeof __TeamGrid
          >[0]["variant"]
        }
      />
    );
  }
  if (layout === "bios") {
    const variant = `image-${imagePosition}${appearance === "accent" ? "-accent" : ""}`;
    return (
      <__TeamBios
        {...props}
        variant={
          (variantOverride ?? variant) as Parameters<
            typeof __TeamBios
          >[0]["variant"]
        }
      />
    );
  }
  const withDetails =
    details ?? members?.some(({ bio, email }) => bio || email) ?? false;
  const variant = (() => {
    if (appearance === "plain") {
      return "default";
    }
    if (appearance === "bordered") {
      return "boxed";
    }
    return appearance;
  })();
  return (() => {
    if (withDetails) {
      return (
        <__TeamCardsDetails
          {...props}
          variant={
            (variantOverride ?? variant) === "rounded"
              ? "default"
              : ((variantOverride ?? variant) as Parameters<
                  typeof __TeamCardsDetails
                >[0]["variant"])
          }
        />
      );
    }
    return (
      <__TeamCards
        {...props}
        variant={
          (variantOverride ?? variant) as Parameters<
            typeof __TeamCards
          >[0]["variant"]
        }
      />
    );
  })();
};

